#include <bits/stdc++.h>
using namespace std;struct C{int s,l,m,e,lm,in,out,g,vl,vth,mode;};struct R{double w,dd;int orders;};R run(vector<int>const&p,C c){int cash=10000,sh=0,pend=0,peak=10000,orders=0,tr=0,mr=0,want=0;long long ss=0,sl=0,sm=0,v=0;double dd=0;for(int i=0;i<p.size();i++){int x=p[i],n=0;if(pend==1){n=min(63,max(0,(cash-5)/x));if(n){cash-=n*x+5;sh+=n;orders++;}}else if(pend==2){n=min(63,sh);if(n&&cash+n*x>=5){cash+=n*x-5;sh-=n;orders++;}}int w=cash+sh*x;peak=max(peak,w);dd=max(dd,double(peak-w)/peak);ss+=x-(i>=c.s?p[i-c.s]:0);sl+=x-(i>=c.l?p[i-c.l]:0);sm+=x-(i>=c.lm?p[i-c.lm]:0);if(i)v+=abs(x-p[i-1])-(i>c.vl?abs(p[i-c.vl]-p[i-c.vl-1]):0);if(i+1>=max({c.l,c.lm,c.vl+1})){long long D=c.s*c.l,d=ss*c.l-sl*c.s;int dm=x*c.lm-sm;int scale=max((long long)c.vl/4,v);if(c.mode&1){if(d*c.vl>c.m*D*scale)tr=1;else if(d*c.vl<-c.e*D*scale)tr=0;if(dm*c.vl<-c.in*c.lm*scale)mr=1;else if(dm*c.vl>c.out*c.lm*scale)mr=0;}else{if(d>c.m*D)tr=1;else if(d<-c.e*D)tr=0;if(dm<-c.in*c.lm)mr=1;else if(dm>c.out*c.lm)mr=0;}bool risky=v*8>c.vth*c.vl;switch(c.mode/2){case 0:want=tr||(mr&&d>=-c.g*D);break;case 1:want=tr||(mr&&d>=-c.g*D&&!risky);break;case 2:want=risky?tr:mr&&d>=-c.g*D;break;case 3:want=risky?tr||(mr&&d>=-c.g*D):mr;break;case 4:want=tr||(mr&&d>=-c.g*D&&risky);break;case 5:want=risky?mr&&d>=-c.g*D:tr;break;}}pend=want?1:2;}return{double(cash+sh*p.back()),dd,orders};}
vector<int>read(string f){ifstream in(f);string s;getline(in,s);vector<int>p;while(getline(in,s))if(s.size())p.push_back(stoi(s.substr(s.find(',')+1)));return p;}
int main(){auto a=read("tb/practica.csv"),b=read("tb/practica_meta.csv");vector<vector<int>> tr;for(auto p:{a,b})for(int i=0;i<12000;i+=3000)tr.emplace_back(p.begin()+i,p.begin()+i+3000);vector<C> cs;mt19937 rng(42);int S[]={8,16,20,32},L[]={64,120,128,256},M[]={2,4,6,8,12,16},LM[]={16,32,60,64,96},IN[]={2,4,6,8,12},OUT[]={0,1,2},G[]={2,4,6,8},VL[]={32,64,128,256},VT[]={3,4,5,6,8,10};for(int i=0;i<30000;i++){C c{S[rng()%4],L[rng()%4],M[rng()%6],M[rng()%6],LM[rng()%5],IN[rng()%5],OUT[rng()%3],G[rng()%4],VL[rng()%4],VT[rng()%6],int(rng()%12)};if(c.s<c.l&&c.lm<=c.l)cs.push_back(c);}vector<pair<double,int>> rs;for(int k=0;k<cs.size();k++){double s[2]={};for(int i=0;i<8;i++){auto r=run(tr[i],cs[k]);s[i/4]+=(log(max(1.,r.w)/10000.)-.5*r.dd)/4;}rs.push_back({(s[0]+s[1])/2-.6*abs(s[0]-s[1]),k});}sort(rs.rbegin(),rs.rend());auto show=[&](C c,double sc){cout<<sc<<" "<<c.s<<" "<<c.l<<" "<<c.m<<" "<<c.e<<" "<<c.lm<<" "<<c.in<<" "<<c.out<<" "<<c.g<<" "<<c.vl<<" "<<c.vth<<" "<<c.mode;for(auto p:{a,b}){auto r=run(p,c);vector<int>h(p.begin()+12000,p.end());auto t=run(h,c);cout<<" full "<<r.w<<" "<<r.dd<<" test "<<t.w<<" "<<t.dd;}cout<<"\n";};for(int i=0;i<20;i++)show(cs[rs[i].second],rs[i].first);}
